<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/layout.php';
require_admin();$mode=is_string($_GET['modo']??null)?$_GET['modo']:'';$edit=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$product=$edit?get_product($edit):null;
if($edit&&!$product)page_error('Artículo no encontrado','El artículo ya no está en el catálogo.',404);
$form=$mode==='agregar'||$product;$products=all_products();$categories=array_values(array_unique(array_column($products,'categoria')));sort($categories);
$q=is_string($_GET['q']??null)?trim(substr($_GET['q'],0,100)):'';$rows=array_filter($products,fn($p)=>$q===''||str_contains(lower($p['nombre'].' '.$p['sku'].' '.$p['marca']),lower($q)));
page_header('Administrar productos');
?>
<main class="container page-section" id="contenido"><div class="page-heading"><div><h1><?=$form?($product?'Modificar artículo':'Agregar artículo'):'Administración'?></h1></div><a class="button <?=$form?'button-light':''?>" href="<?=h(url($form?'admin.php':'admin.php?modo=agregar'))?>"><?=icon($form?'arrow':'plus')?><?=$form?'Volver al listado':'Agregar artículo'?></a></div>
<?php if($form):$p=$product??['id'=>'','sku'=>'','nombre'=>'','marca'=>'','categoria'=>'','descripcion'=>'','detalle'=>'','precio'=>'','stock'=>0,'imagen_url'=>'','destacado'=>false,'updated_at'=>''];?>
<form class="admin-form" data-api="product_save" method="post" action="<?=h(url('api.php'))?>" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=h($p['id'])?>"><input type="hidden" name="version" value="<?=h($p['updated_at'])?>"><section class="form-panel"><div class="panel-heading"><h2>Información del producto</h2></div><div class="field"><label for="nombre">Nombre del producto</label><input id="nombre" name="nombre" value="<?=h($p['nombre'])?>" minlength="3" maxlength="120" required></div><div class="form-grid"><div class="field"><label for="marca">Marca</label><input id="marca" name="marca" value="<?=h($p['marca'])?>" maxlength="60" required></div><div class="field"><label for="sku">Código / SKU</label><input id="sku" name="sku" value="<?=h($p['sku'])?>" maxlength="40" minlength="3" pattern="[A-Za-z0-9][A-Za-z0-9_.\-]{2,39}" required placeholder="PB-001"></div></div><div class="field"><label for="categoria">Categoría</label><input id="categoria" name="categoria" value="<?=h($p['categoria'])?>" maxlength="60" minlength="2" list="categorias" required placeholder="Elegí o escribí una categoría"><datalist id="categorias"><?php foreach($categories as $cat):?><option value="<?=h($cat)?>"><?php endforeach;?></datalist></div><div class="field"><label for="descripcion">Descripción breve</label><textarea id="descripcion" name="descripcion" rows="3" minlength="10" maxlength="600" required><?=h($p['descripcion'])?></textarea></div><div class="field"><label for="detalle">Detalle y características <span class="muted">(opcional)</span></label><textarea id="detalle" name="detalle" rows="5" maxlength="4000"><?=h($p['detalle'])?></textarea></div></section><aside class="form-panel"><h2>Imagen y disponibilidad</h2><div class="upload-preview"><img id="image-preview" src="<?=h(image_url($p['imagen_url']))?>" alt="Vista previa de la foto del artículo" width="360" height="270"></div><div class="field"><label class="file-label" for="imagen"><?=icon('upload')?>Subir imagen</label><input class="file-input" id="imagen" type="file" name="imagen" accept="image/jpeg,image/png,image/webp" data-image-upload><small>JPG, PNG o WebP. Hasta 5 MB.</small></div><div class="field"><label for="imagen_url">O usar una URL de imagen</label><input id="imagen_url" name="imagen_url" value="<?=h($p['imagen_url'])?>" maxlength="1500" placeholder="https://..." data-image-url><small>Si subís una foto, se usará esa imagen.</small></div><div class="form-grid"><div class="field"><label for="precio">Precio (ARS)</label><input id="precio" type="number" name="precio" value="<?=h($p['precio'])?>" min="0.01" max="999999999" step="0.01" required></div><div class="field"><label for="stock">Stock</label><input id="stock" type="number" name="stock" value="<?=h($p['stock'])?>" min="0" max="99999" step="1" required></div></div><label class="checkbox-label"><input type="checkbox" name="destacado" value="1" <?=$p['destacado']?'checked':''?>>Mostrar en destacados</label><p class="form-message" data-form-message role="alert" hidden></p><button class="button button-full" type="submit"><?=icon('check')?>Guardar artículo</button><a class="button button-plain button-full" href="<?=h(url('admin.php'))?>">Cancelar</a></aside></form>
<?php else:?>
<div class="admin-toolbar"><nav class="category-tabs" aria-label="Acciones del administrador"><a class="<?=$mode===''?'selected':''?>" href="<?=h(url('admin.php'))?>">Todos los artículos</a><a class="<?=$mode==='modificar'?'selected':''?>" href="<?=h(url('admin.php?modo=modificar'))?>">Modificar</a><a class="<?=$mode==='eliminar'?'selected':''?>" href="<?=h(url('admin.php?modo=eliminar'))?>">Eliminar</a></nav><form class="search-field" method="get" action="<?=h(url('admin.php'))?>"><input type="hidden" name="modo" value="<?=h($mode)?>"><?=icon('search')?><input type="search" name="q" value="<?=h($q)?>" placeholder="Buscar por nombre o código" aria-label="Buscar artículos"><button type="submit" class="search-submit" aria-label="Buscar"><?=icon('arrow')?></button></form></div><p class="admin-count"><?=count($rows)?> artículos</p>
<?php if($rows):?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Producto</th><th>Código</th><th>Precio</th><th>Stock</th><th class="align-right">Acciones</th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><div class="admin-product"><img src="<?=h(image_url($p['imagen_url']))?>" alt="" width="58" height="58"><div><strong><?=h($p['nombre'])?></strong><small><?=h($p['marca'].' · '.$p['categoria'])?></small></div></div></td><td><span class="sku"><?=h($p['sku'])?></span></td><td><?=money($p['precio'])?></td><td><span class="stock-label <?=(int)$p['stock']>0?'':'no-stock'?>"><i></i><?=(int)$p['stock']?></span></td><td><div class="table-actions"><?php if($mode!=='eliminar'):?><a class="button button-small button-light" href="<?=h(url('admin.php?id='.$p['id']))?>"><?=icon('edit')?><span>Modificar</span></a><?php endif;?><?php if($mode!=='modificar'):?><button type="button" class="icon-button danger" data-delete-product="<?=(int)$p['id']?>" data-product-name="<?=h($p['nombre'])?>" aria-label="Eliminar <?=h($p['nombre'])?>"><?=icon('trash')?></button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h2>No hay artículos para mostrar.</h2><a class="button" href="<?=h(url('admin.php?modo=agregar'))?>">Agregar artículo<?=icon('plus')?></a></div><?php endif;?>
<?php endif;?></main>
<?php page_footer(); ?>
